"use client"

import { useEffect, useState, type FormEvent } from "react"
import Link from "next/link"
import { ArrowDown, ArrowUp, Download, Eye, FileCheck2, History, MoreHorizontal, Plus, Search, Settings2, Upload } from "lucide-react"
import { toast } from "sonner"
import { Line, LineChart, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis } from "recharts"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { EvidenceList, FieldInput, FormField, Modal, ReferenceInput } from "@/components/pesv/planning-module"
import { currentYear, dateToday, ids, loadCatalogs, readStore, text, validateRecord, type Catalogs, type Evidence, type Values } from "@/lib/pesv/planning"
import { INDICATORS_KEY, activeMeasurements, aggregate, annualReportKind, compute, definitions, demonstrationMeasurements, emptySheet, expectedPeriods, formulaLabel, initialIndicatorsState, losses, makeAnnualReport, measurementKey, methodologySource, periodLabel, periodRange, protocolKind, quarterEnd, reportInitialValues, reportSourceRows, reportWarnings, sourceSuggestion, stepNames, validateMeasurement, type AnnualReport, type CsvReview, type IndicatorDefinition, type IndicatorSheet, type IndicatorsState, type Level, type Measurement, type ReportRow, type StepResult } from "@/lib/pesv/indicators"
import { downloadAnnualReport, downloadCsvReview, downloadIndicatorSummary, downloadMeasurement, resultLabel } from "@/lib/pesv/indicators-pdf"
import { auditReportSteps } from "@/lib/pesv/indicators"

const selectClass = "h-10 w-full min-w-0 rounded-md border bg-background px-3 text-sm"
const tableHead = "bg-blue-50 text-blue-900 dark:bg-blue-950 dark:text-blue-100"
const cell = "px-4 py-3 text-left align-top"
const blankMeasurement = { year: "", period: "1", loss: losses[0], numerator: "", denominator: "", source: "", sourceDetails: "", analysis: "", correctionReason: "" }
type UploadTarget = { scope: "protocol" | "measurement" | "review" | "report"; id: string; purpose?: string }
type ReportRows = { fleet: ReportRow[]; actors: ReportRow[]; contractors: ReportRow[]; fines: ReportRow[] }

export default function PesvIndicatorsPage() {
  const [state, setState] = useState<IndicatorsState>(initialIndicatorsState)
  const [catalogs, setCatalogs] = useState<Catalogs>(loadCatalogs)
  const [ready, setReady] = useState(false)
  const [tab, setTab] = useState("indicators")
  const [year, setYear] = useState(String(currentYear()))
  const [quarter, setQuarter] = useState(String(Math.ceil(Number(dateToday().slice(5, 7)) / 3)))
  const [query, setQuery] = useState("")
  const [sheetTarget, setSheetTarget] = useState<IndicatorDefinition | null>(null)
  const [sheetForm, setSheetForm] = useState<IndicatorSheet | null>(null)
  const [measurementTarget, setMeasurementTarget] = useState<IndicatorDefinition | null>(null)
  const [measurementForm, setMeasurementForm] = useState(blankMeasurement)
  const [rectifying, setRectifying] = useState<Measurement | null>(null)
  const [detailId, setDetailId] = useState<string | null>(null)
  const [reviewOpen, setReviewOpen] = useState(false)
  const [reviewForm, setReviewForm] = useState({ year, quarter, date: dateToday(), reviewers: [] as string[], conclusion: "", decisions: "" })
  const [reviewDetail, setReviewDetail] = useState<string | null>(null)
  const [reportOpen, setReportOpen] = useState(false)
  const [reportForm, setReportForm] = useState<Values>({})
  const [reportRows, setReportRows] = useState<ReportRows>({ fleet: [], actors: [], contractors: [], fines: [] })
  const [steps, setSteps] = useState<StepResult[]>([])
  const [reportDetail, setReportDetail] = useState<string | null>(null)
  const [protocolOpen, setProtocolOpen] = useState(false)
  const [protocolForm, setProtocolForm] = useState<Values>({})
  const [levelForm, setLevelForm] = useState<Level>("Básico")
  const [constantForm, setConstantForm] = useState("5000000")
  const [costMethodForm, setCostMethodForm] = useState<"SUM" | "PRODUCT">("SUM")
  const [uploadTarget, setUploadTarget] = useState<UploadTarget | null>(null)
  const [uploading, setUploading] = useState(false)
  const [file, setFile] = useState<File | null>(null)
  const [preview, setPreview] = useState<Evidence | null>(null)
  const [presentationTarget, setPresentationTarget] = useState<string | null>(null)
  const [presentationForm, setPresentationForm] = useState({ date: dateToday(), authority: "", reference: "" })
  const [committeeMembers, setCommitteeMembers] = useState<{ value: string; label: string }[]>([])

  function refresh() {
    setCatalogs(loadCatalogs())
    const committee = readStore<{ members: { employeeId: string; employeeName: string }[] } | null>("safecloud:pesv-committee", null)
    setCommitteeMembers((committee?.members ?? []).map(m => ({ value: m.employeeId, label: m.employeeName })))
  }
  useEffect(() => {
    const stored = readStore<IndicatorsState | null>(INDICATORS_KEY, null)
    const initial = stored ?? initialIndicatorsState()
    if (!stored) {
      initial.measurements = demonstrationMeasurements(initial)
      initial.sheets = initial.measurements.map(m => m.sheet)
      try { localStorage.setItem(INDICATORS_KEY, JSON.stringify(initial)) } catch { toast.error("No se pudieron guardar los datos de demostración.") }
    }
    setState(initial); refresh(); setReady(true)
    window.addEventListener("focus", refresh); window.addEventListener("storage", refresh)
    return () => { window.removeEventListener("focus", refresh); window.removeEventListener("storage", refresh) }
  }, [])
  function persist(next: IndicatorsState, event: string, details = "") {
    const withHistory = { ...next, history: [...next.history, { at: new Date().toISOString(), event, details }] }
    try { localStorage.setItem(INDICATORS_KEY, JSON.stringify(withHistory)); setState(withHistory); return true }
    catch { toast.error("No se pudo guardar. Reduce el tamaño del archivo o libera espacio en el navegador."); return false }
  }
  if (!ready) return <p className="p-6 text-sm text-muted-foreground">Cargando indicadores…</p>
  const active = activeMeasurements(state.measurements)
  const selectedDefinitions = definitions.filter(d => d.levels.includes(state.level) && `${d.name} ${d.code}`.toLowerCase().includes(query.toLowerCase()))
  const years = [...new Set([String(currentYear()), String(currentYear() - 1), ...state.sheets.map(s => s.year), ...state.measurements.map(m => m.year), ...state.reports.map(r => text(r.values.year))])].sort().reverse()
  const sheetFor = (definition: IndicatorDefinition, selectedYear = year) => state.sheets.find(s => s.id === definition.id && s.year === selectedYear) ?? emptySheet(definition, selectedYear)
  const currentDetail = state.measurements.find(m => m.id === detailId)
  const currentReview = state.reviews.find(r => r.id === reviewDetail)
  const currentReport = state.reports.find(r => r.id === reportDetail)
  const reports = state.reports.filter(r => text(r.values.year) === year)
  const reviews = state.reviews.filter(r => r.year === year)
  const measured = selectedDefinitions.filter(d => (d.loss ? losses : [""]).every(loss => {
    const result = aggregate(d, state.measurements, year, Number(quarter), loss)
    return result.count > 0 && !result.missing.length
  })).length

  function openSheet(definition: IndicatorDefinition) { refresh(); setSheetTarget(definition); setSheetForm(structuredClone(sheetFor(definition))) }
  function saveSheet(event: FormEvent) {
    event.preventDefault()
    if (!sheetTarget || !sheetForm) return
    const numbers = [sheetForm.baseline, sheetForm.target].map(Number)
    if (!sheetForm.name.trim() || !sheetForm.description.trim() || !sheetForm.sources.trim() || !sheetForm.sourceReliability.trim() || !sheetForm.responsibleId || sheetForm.baseline.trim() === "" || sheetForm.target.trim() === "" || numbers.some(n => !Number.isFinite(n))) { toast.error("Completa la ficha y registra línea base y meta numéricas."); return }
    if (sheetTarget.formula === "PERCENTAGE" && numbers.some(n => n < 0 || n > 100)) { toast.error("La línea base y meta porcentuales deben estar entre 0 y 100."); return }
    if (sheetTarget.formula !== "DIFFERENCE" && numbers.some(n => n < 0)) { toast.error("La línea base y meta no pueden ser negativas para este indicador."); return }
    if (sheetTarget.direction === "Aumentar" ? numbers[1] < numbers[0] : numbers[1] > numbers[0]) { toast.error("La meta debe respetar el sentido de evolución del indicador."); return }
    const linked = catalogs.workActivities.filter(o => sheetForm.workActivityIds.includes(o.value))
    if (linked.some(o => o.year && o.year !== sheetForm.year)) { toast.error("Relaciona actividades de la misma vigencia del indicador."); return }
    const saved = { ...sheetForm, name: `${sheetTarget.direction}: ${sheetForm.name.replace(/^(Aumentar|Reducir):\s*/, "").trim()}`, workActivityNames: linked.map(o => o.label) }
    if (persist({ ...state, sheets: [...state.sheets.filter(s => s.id !== saved.id || s.year !== saved.year), saved] }, "Ficha de indicador actualizada", `${saved.name} · ${saved.year}`)) { setSheetTarget(null); toast.success("Ficha guardada; las mediciones anteriores conservan su versión.") }
  }
  function openMeasurement(definition: IndicatorDefinition, previous?: Measurement) {
    setMeasurementTarget(definition); setRectifying(previous ?? null)
    const defaultPeriod = definition.frequency === "Anual" ? "1" : definition.frequency === "Trimestral" ? quarter : String(Number(dateToday().slice(5, 7)))
    setMeasurementForm(previous ? { year: previous.year, period: previous.period, loss: previous.loss, numerator: String(previous.numerator), denominator: String(previous.denominator), analysis: previous.analysis, source: previous.source, sourceDetails: previous.sourceDetails, correctionReason: "" } : { ...blankMeasurement, year, period: defaultPeriod })
  }
  function suggestMeasurement() {
    if (!measurementTarget) return
    const suggestion = sourceSuggestion(measurementTarget, measurementForm.year, measurementForm.period, sheetFor(measurementTarget, measurementForm.year), measurementForm.loss)
    if (!suggestion) { toast.info("Esta fuente no tiene las variables necesarias. Diligencia los datos verificados del corte."); return }
    setMeasurementForm(prev => ({ ...prev, ...suggestion, sourceDetails: suggestion.details, source: measurementTarget.sources }))
  }
  function saveMeasurement(event: FormEvent) {
    event.preventDefault()
    if (!measurementTarget) return
    const sheet = rectifying?.sheet ?? sheetFor(measurementTarget, measurementForm.year)
    const error = validateMeasurement(measurementTarget, sheet, measurementForm, state, rectifying ?? undefined)
    if (error) { toast.error(error); return }
    const numerator = Number(measurementForm.numerator), denominator = Number(measurementForm.denominator)
    const record: Measurement = { id: crypto.randomUUID(), indicatorId: measurementTarget.id, year: measurementForm.year, period: measurementForm.period, loss: measurementTarget.loss ? measurementForm.loss : "", numerator, denominator, result: compute(measurementTarget, numerator, denominator, rectifying?.rateConstant ?? state.rateConstant, rectifying?.costMethod ?? state.costMethod), definition: structuredClone(measurementTarget), sheet: structuredClone(rectifying?.sheet ?? sheet), rateConstant: rectifying?.rateConstant ?? state.rateConstant, costMethod: rectifying?.costMethod ?? state.costMethod, analysis: measurementForm.analysis.trim(), source: measurementForm.source.trim(), sourceDetails: measurementForm.sourceDetails, registeredAt: new Date().toISOString(), evidence: [], ...(rectifying ? { supersedesId: rectifying.id, correctionReason: measurementForm.correctionReason.trim() } : {}) }
    if (persist({ ...state, measurements: [...state.measurements, record] }, rectifying ? "Medición rectificada" : "Medición registrada", `${record.sheet.name} · ${record.year} · ${periodLabel(record.definition, record.period)} · ${record.loss}${record.correctionReason ? ` · ${record.correctionReason}` : ""}`)) { setMeasurementTarget(null); toast.success("Medición guardada. Ya puedes cargar sus soportes.") }
  }
  function openReview() { refresh(); setReviewForm({ year, quarter, date: dateToday(), reviewers: [], conclusion: "", decisions: "" }); setReviewOpen(true) }
  function saveReview(event: FormEvent) {
    event.preventDefault()
    const cutoff = quarterEnd(reviewForm.year, reviewForm.quarter)
    if (!reviewForm.reviewers.length || reviewForm.date < cutoff || reviewForm.date > dateToday() || !reviewForm.conclusion.trim() || !reviewForm.decisions.trim()) { toast.error("Selecciona revisores del CSV, conclusiones y decisiones; la revisión debe realizarse después del corte y no en el futuro."); return }
    if (reviewForm.reviewers.some(id => !committeeMembers.some(m => m.value === id))) { toast.error("El equipo revisor cambió; selecciona miembros vigentes del CSV."); return }
    const records = active.filter(m => m.year === reviewForm.year && periodRange(m.year, m.definition.frequency, m.period).end <= cutoff)
    if (!records.length) { toast.error("Registra mediciones del corte antes de crear la revisión."); return }
    const record: CsvReview = { id: crypto.randomUUID(), year: reviewForm.year, quarter: reviewForm.quarter, date: reviewForm.date, reviewerIds: reviewForm.reviewers, reviewerNames: committeeMembers.filter(m => reviewForm.reviewers.includes(m.value)).map(m => m.label), conclusion: reviewForm.conclusion.trim(), decisions: reviewForm.decisions.trim(), measurements: structuredClone(records), evidence: [], createdAt: new Date().toISOString() }
    if (persist({ ...state, reviews: [...state.reviews, record] }, "Revisión CSV registrada", `Trimestre ${record.quarter} · ${record.year}`)) { setReviewOpen(false); toast.success("Revisión guardada. Carga el acta desde sus acciones.") }
  }
  function openReport(previous?: AnnualReport) {
    const values = previous ? structuredClone(previous.values) : reportInitialValues(year)
    setReportForm(values); setReportRows(previous ? structuredClone({ fleet: previous.fleet, actors: previous.actors, contractors: previous.contractors, fines: previous.fines }) : reportSourceRows(text(values.year)))
    setSteps(previous ? structuredClone(previous.steps) : auditReportSteps(year)); setReportOpen(true)
  }
  function saveReport(event: FormEvent) {
    event.preventDefault()
    const error = validateRecord(annualReportKind, reportForm, [], catalogs)
    if (error) { toast.error(error); return }
    if (text(reportForm.auditDate) > `${text(reportForm.year)}-12-31` || text(reportForm.auditDate) > dateToday() || text(reportForm.auditDate).slice(0, 4) !== text(reportForm.year)) { toast.error("La auditoría debe estar realizada dentro del año reportado."); return }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text(reportForm.leaderEmail))) { toast.error("Revisa el correo institucional del líder PESV."); return }
    if (Object.values(reportRows).some(rows => rows.some(row => !row.label.trim() || !Number.isInteger(row.count) || row.count < 0))) { toast.error("Cada fila requiere identificación y una cantidad entera no negativa."); return }
    const report = makeAnnualReport(reportForm, reportRows, steps, state)
    if (persist({ ...state, reports: [...state.reports, report] }, "Reporte anual generado", `${text(report.values.companyName)} · ${text(report.values.year)} · ${report.id}`)) { setReportOpen(false); setReportDetail(report.id); toast.success("Versión del reporte guardada con los datos actuales.") }
  }
  function openProtocol() { setProtocolForm(structuredClone(state.protocol)); setLevelForm(state.level); setConstantForm(String(state.rateConstant)); setCostMethodForm(state.costMethod); setProtocolOpen(true) }
  function saveProtocol(event: FormEvent) {
    event.preventDefault()
    const error = validateRecord(protocolKind, protocolForm, [], catalogs)
    if (error) { toast.error(error); return }
    if (!Number.isFinite(Number(constantForm)) || Number(constantForm) <= 0) { toast.error("La constante de kilómetros debe ser mayor que cero."); return }
    if (persist({ ...state, protocol: protocolForm, level: levelForm, rateConstant: Number(constantForm), costMethod: costMethodForm }, "Protocolo de indicadores actualizado", `Nivel ${levelForm} · K ${constantForm} · Costos ${costMethodForm} · Versión ${text(protocolForm.version)}`)) { setProtocolOpen(false); toast.success("Protocolo actualizado; se conservan los cálculos anteriores.") }
  }
  function openUpload(target: UploadTarget) { setFile(null); setUploadTarget(target) }
  async function upload(event: FormEvent) {
    event.preventDefault()
    if (!file || !uploadTarget) return
    if (file.size > 3 * 1024 * 1024 || !(file.type.startsWith("image/") || file.type === "application/pdf")) { toast.error("Selecciona un PDF o imagen de hasta 3 MB."); return }
    if (uploadTarget.purpose === "AUDIT" && file.type !== "application/pdf") { toast.error("El informe de auditoría debe ser un archivo PDF."); return }
    setUploading(true)
    try {
      const url = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file!) })
      const evidence: Evidence = { id: crypto.randomUUID(), name: file.name, mime: file.type, uploadedAt: new Date().toISOString(), url, targetId: uploadTarget.purpose }
      const next = { ...state }
      if (uploadTarget.scope === "protocol") next.protocolEvidence = [...state.protocolEvidence, evidence]
      if (uploadTarget.scope === "measurement") next.measurements = state.measurements.map(m => m.id === uploadTarget.id ? { ...m, evidence: [...m.evidence, evidence] } : m)
      if (uploadTarget.scope === "review") next.reviews = state.reviews.map(r => r.id === uploadTarget.id ? { ...r, evidence: [...r.evidence, evidence] } : r)
      if (uploadTarget.scope === "report") next.reports = state.reports.map(r => r.id === uploadTarget.id ? { ...r, evidence: [...r.evidence, evidence] } : r)
      if (persist(next, "Evidencia cargada", `${file.name} · ${uploadTarget.scope} · ${uploadTarget.id} · ${uploadTarget.purpose ?? "Soporte"}`)) { setUploadTarget(null); toast.success("Evidencia cargada") }
    } catch { toast.error("No se pudo leer el archivo.") } finally { setUploading(false) }
  }
  function savePresentation(event: FormEvent) {
    event.preventDefault()
    const report = state.reports.find(r => r.id === presentationTarget)
    if (!report) return
    if (reportWarnings(report, text(report.values.level) as Level).length) { toast.error("Completa los pendientes del reporte antes de registrar su presentación."); return }
    if (!report.evidence.some(e => e.targetId === "SIGNED") || !report.evidence.some(e => e.targetId === "RECEIPT")) { toast.error("Carga el documento firmado y el soporte de radicación antes de registrar la presentación."); return }
    if (presentationForm.date < `${Number(report.values.year) + 1}-01-01` || presentationForm.date > dateToday() || !presentationForm.authority.trim() || !presentationForm.reference.trim()) { toast.error("Revisa la fecha, autoridad y número de radicado de la presentación real."); return }
    const entry = { ...presentationForm, at: new Date().toISOString() }
    if (persist({ ...state, reports: state.reports.map(r => r.id === report.id ? { ...r, presentations: [...r.presentations, entry] } : r) }, "Presentación de autogestión registrada", `${entry.authority} · ${entry.reference} · ${entry.date}`)) { setPresentationTarget(null); toast.success("Presentación registrada.") }
  }

  return <div className="space-y-5">
    <header className="flex flex-wrap items-center justify-between gap-3"><div><h1 className="text-2xl font-bold">Indicadores y autogestión PESV</h1><p className="mt-1 text-sm text-muted-foreground">Medición, evaluación del CSV y reporte anual</p></div><Badge variant="outline">Nivel {state.level}</Badge></header>
    <Tabs value={tab} onValueChange={setTab}><TabsList className="h-auto max-w-full flex-wrap justify-start">{[["indicators", "Indicadores"], ["reviews", "Revisión del CSV"], ["reports", "Autogestión anual"], ["protocol", "Protocolo"]].map(([value, label]) => <TabsTrigger key={value} value={value} className="min-h-9 whitespace-normal">{label}</TabsTrigger>)}</TabsList></Tabs>
    <div className="flex flex-wrap items-center gap-3"><select className={`${selectClass} sm:w-32`} aria-label="Vigencia" value={year} onChange={e => setYear(e.target.value)}>{years.map(y => <option key={y}>{y}</option>)}</select>{tab !== "reports" && tab !== "protocol" && <select className={`${selectClass} sm:w-60`} aria-label="Corte trimestral" value={quarter} onChange={e => setQuarter(e.target.value)}>{["1", "2", "3", "4"].map(q => <option key={q} value={q}>Trimestre {q} · {quarterEnd(year, q)}</option>)}</select>}{tab === "indicators" && <><div className="relative min-w-48 flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="pl-9" aria-label="Buscar indicadores" placeholder="Buscar indicador" value={query} onChange={e => setQuery(e.target.value)} /></div><Button variant="outline" onClick={() => downloadIndicatorSummary(state, year, Number(quarter))}><Download className="mr-2 h-4 w-4" />Descargar resultados</Button></>}{tab === "reviews" && <Button className="ml-auto" onClick={openReview}><Plus className="mr-2 h-4 w-4" />Nueva revisión CSV</Button>}{tab === "reports" && <Button className="ml-auto" onClick={() => openReport()}><Plus className="mr-2 h-4 w-4" />Nuevo reporte anual</Button>}</div>
    {tab === "indicators" && <>
      <div className="flex flex-wrap justify-center gap-x-8 gap-y-2 text-sm"><span>Indicadores aplicables: <strong>{selectedDefinitions.length}</strong></span><span>Con cortes completos: <strong className="text-green-700">{measured}</strong></span><span>Pendientes: <strong className="text-amber-700">{selectedDefinitions.length - measured}</strong></span></div>
      <section className="overflow-hidden rounded-lg border bg-card"><h2 className="border-b px-4 py-3 font-semibold">Indicadores de seguridad vial</h2><div className="overflow-x-auto"><table className="w-full text-sm"><thead className={tableHead}><tr>{["Indicador", "Frecuencia", "Línea base / meta", "Acumulado al corte", ""].map((label, i) => <th className={cell} key={i}>{label}</th>)}</tr></thead><tbody>{selectedDefinitions.map(d => { const sheet = sheetFor(d); return <tr key={d.id} className="border-b last:border-0 hover:bg-muted/30"><td className={`${cell} min-w-72`}><p className="text-xs text-muted-foreground">{d.code}</p><p className="font-medium">{sheet.name}</p><p className="mt-1 text-xs text-muted-foreground">{d.description}</p><span className="mt-1 inline-flex items-center gap-1 text-xs text-primary">{d.direction === "Aumentar" ? <ArrowUp className="h-3 w-3" /> : <ArrowDown className="h-3 w-3" />}{d.direction === "Aumentar" ? "Mayor es mejor" : "Menor es mejor"}</span></td><td className={`${cell} whitespace-nowrap`}>{d.frequency}</td><td className={cell}>{sheet.baseline !== "" ? `${sheet.baseline} ${d.unit}` : "Sin definir"}<p className="text-xs text-muted-foreground">Meta: {sheet.target || "Sin definir"}</p></td><td className={`${cell} min-w-48`}>{(d.loss ? losses : [""]).map(loss => { const a = aggregate(d, state.measurements, year, Number(quarter), loss); return <div key={loss} className="mb-2 last:mb-0">{loss && <p className="text-xs text-muted-foreground">{loss}</p>}<p className={a.value === null ? "text-amber-700" : "font-medium"}>{a.value === null ? a.reason : resultLabel(a.value, d)}</p>{a.missing.length > 0 && <p className="text-xs text-muted-foreground">{a.missing.length} corte(s) pendiente(s)</p>}</div> })}</td><td className={cell}><Actions label={`Acciones de ${d.code}`}><DropdownMenuItem onSelect={() => openSheet(d)}><Settings2 className="mr-2 h-4 w-4" />Configurar ficha</DropdownMenuItem><DropdownMenuItem onSelect={() => openMeasurement(d)}><Plus className="mr-2 h-4 w-4" />Registrar medición</DropdownMenuItem><DropdownMenuItem onSelect={() => { setSheetTarget(d); setSheetForm(null) }}><Eye className="mr-2 h-4 w-4" />Ver ficha e historial</DropdownMenuItem></Actions></td></tr> })}</tbody></table></div></section>
    </>}
    {tab === "reviews" && <section className="overflow-hidden rounded-lg border bg-card"><h2 className="border-b px-4 py-3 font-semibold">Revisiones trimestrales del CSV</h2><div className="overflow-x-auto"><table className="w-full text-sm"><thead className={tableHead}><tr>{["Corte", "Fecha de revisión", "Revisores", "Estado", ""].map((l, i) => <th key={i} className={cell}>{l}</th>)}</tr></thead><tbody>{reviews.map(r => <tr className="border-b" key={r.id}><td className={cell}>{quarterEnd(r.year, r.quarter)}</td><td className={cell}>{r.date}</td><td className={cell}>{r.reviewerNames.join(" · ")}</td><td className={cell}><Badge variant="outline">{r.evidence.length ? "Documentada" : "Pendiente de acta"}</Badge></td><td className={cell}><Actions label={`Acciones de revisión ${r.id}`}><DropdownMenuItem onSelect={() => setReviewDetail(r.id)}><Eye className="mr-2 h-4 w-4" />Ver revisión</DropdownMenuItem><DropdownMenuItem onSelect={() => openUpload({ scope: "review", id: r.id })}><Upload className="mr-2 h-4 w-4" />Cargar acta / evidencia</DropdownMenuItem><DropdownMenuItem onSelect={() => downloadCsvReview(r)}><Download className="mr-2 h-4 w-4" />Descargar acta</DropdownMenuItem></Actions></td></tr>)}</tbody></table></div>{!reviews.length && <Empty>Sin revisiones registradas para esta vigencia.</Empty>}</section>}
    {tab === "reports" && <><div className="flex flex-wrap justify-center gap-x-8 gap-y-2 text-sm"><span>Corte anual: <strong>{year}-12-31</strong></span><span>Fecha límite de referencia: <strong>{Number(year) + 1}-01-31</strong></span><span>Versiones: <strong>{reports.length}</strong></span></div><section className="overflow-hidden rounded-lg border bg-card"><h2 className="border-b px-4 py-3 font-semibold">Reportes anuales de autogestión</h2><div className="overflow-x-auto"><table className="w-full text-sm"><thead className={tableHead}><tr>{["Empresa / versión", "Vigencia", "Generado", "Estado", ""].map((l, i) => <th key={i} className={cell}>{l}</th>)}</tr></thead><tbody>{reports.map((r, index) => { const warnings = reportWarnings(r, text(r.values.level) as Level); return <tr className="border-b" key={r.id}><td className={cell}><strong>{text(r.values.companyName)}</strong><p className="text-xs text-muted-foreground">Versión {index + 1}</p></td><td className={cell}>{text(r.values.year)}</td><td className={cell}>{new Date(r.createdAt).toLocaleDateString("es-CO", { timeZone: "America/Bogota" })}</td><td className={cell}><Badge variant="outline">{r.presentations.length ? "Presentado" : warnings.length ? "Borrador" : "Listo para revisión"}</Badge>{r.presentations.at(-1) && r.presentations.at(-1)!.date > `${Number(r.values.year) + 1}-01-31` && <p className="mt-1 text-xs text-red-600">Presentación posterior al plazo de referencia</p>}</td><td className={cell}><Actions label={`Acciones del reporte ${r.id}`}><DropdownMenuItem onSelect={() => setReportDetail(r.id)}><Eye className="mr-2 h-4 w-4" />Ver reporte y pendientes</DropdownMenuItem><DropdownMenuItem onSelect={() => downloadAnnualReport(r)}><Download className="mr-2 h-4 w-4" />Descargar PDF</DropdownMenuItem><DropdownMenuItem onSelect={() => openUpload({ scope: "report", id: r.id, purpose: "AUDIT" })}><Upload className="mr-2 h-4 w-4" />Cargar informe de auditoría</DropdownMenuItem><DropdownMenuItem onSelect={() => openUpload({ scope: "report", id: r.id, purpose: "SIGNED" })}><Upload className="mr-2 h-4 w-4" />Cargar documento firmado</DropdownMenuItem><DropdownMenuItem onSelect={() => openUpload({ scope: "report", id: r.id, purpose: "RECEIPT" })}><Upload className="mr-2 h-4 w-4" />Cargar soporte de radicación</DropdownMenuItem><DropdownMenuItem disabled={warnings.length > 0 || r.presentations.length > 0} onSelect={() => { setPresentationTarget(r.id); setPresentationForm({ date: dateToday(), authority: text(r.values.authority), reference: "" }) }}><FileCheck2 className="mr-2 h-4 w-4" />Registrar presentación</DropdownMenuItem><DropdownMenuSeparator /><DropdownMenuItem onSelect={() => openReport(r)}><Plus className="mr-2 h-4 w-4" />Crear versión actualizada</DropdownMenuItem></Actions></td></tr> })}</tbody></table></div>{!reports.length && <Empty>Sin reportes registrados para esta vigencia.</Empty>}</section></>}
    {tab === "protocol" && <section className="space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><h2 className="font-semibold">{text(state.protocol.name)}</h2><div className="flex gap-2"><Button variant="outline" onClick={openProtocol}><Settings2 className="mr-2 h-4 w-4" />Editar protocolo</Button><Button variant="outline" onClick={() => openUpload({ scope: "protocol", id: "protocol" })}><Upload className="mr-2 h-4 w-4" />Cargar evidencia</Button></div></div><dl className="grid gap-4 md:grid-cols-2">{protocolKind.fields.map(f => <div key={f.key} className={f.wide ? "md:col-span-2" : ""}><dt className="text-xs text-muted-foreground">{f.label}</dt><dd className="mt-1 whitespace-pre-wrap text-sm">{f.reference ? catalogs.people.find(p => p.value === state.protocol[f.key])?.label : text(state.protocol[f.key])}</dd></div>)}</dl><div className="flex flex-wrap gap-5 border-y py-3 text-sm"><span>Constante de tasa: <strong>{state.rateConstant.toLocaleString("es-CO")} km</strong></span><span>Costos: <strong>{state.costMethod === "SUM" ? "Directos + indirectos" : "Directos × indirectos · por validar"}</strong></span><a href={methodologySource} target="_blank" rel="noreferrer" className="text-primary underline">Referencia metodológica</a></div><EvidenceList evidence={state.protocolEvidence} onPreview={setPreview} /><h3 className="flex items-center gap-2 font-semibold"><History className="h-4 w-4" />Historial</h3>{state.history.slice().reverse().map((event, i) => <div key={i} className="border-l-2 border-blue-300 pl-3 text-sm"><p className="text-xs text-muted-foreground">{new Date(event.at).toLocaleString("es-CO", { timeZone: "America/Bogota" })}</p><p>{event.event}</p><p className="break-words text-muted-foreground">{event.details}</p></div>)}</section>}

    <Modal open={!!sheetTarget} onOpenChange={open => !open && setSheetTarget(null)} title={sheetTarget?.name || "Ficha"} footer={sheetForm && <><Button variant="outline" onClick={() => setSheetTarget(null)}>Cancelar</Button><Button type="submit" form="pesv-indicator-sheet">Guardar ficha</Button></>}>
      {sheetTarget && sheetForm ? <form id="pesv-indicator-sheet" onSubmit={saveSheet} className="grid gap-4 md:grid-cols-2"><FormField label="Nombre del indicador"><Input aria-label="Nombre del indicador" required value={sheetForm.name} onChange={e => setSheetForm({ ...sheetForm, name: e.target.value })} /></FormField><FormField label="Sentido esperado"><Input readOnly value={sheetTarget.direction} /></FormField><div className="md:col-span-2"><FormField label="Qué se mide"><Textarea aria-label="Qué se mide" required value={sheetForm.description} onChange={e => setSheetForm({ ...sheetForm, description: e.target.value })} /></FormField></div><FormField label={`Línea base (${sheetTarget.unit})`}><Input aria-label="Línea base" required type="number" step="any" value={sheetForm.baseline} onChange={e => setSheetForm({ ...sheetForm, baseline: e.target.value })} /></FormField><FormField label={`Meta (${sheetTarget.unit})`}><Input aria-label="Meta" required type="number" step="any" value={sheetForm.target} onChange={e => setSheetForm({ ...sheetForm, target: e.target.value })} /></FormField><div className="md:col-span-2"><FormField label="Fuentes de información"><Textarea aria-label="Fuentes de información" required value={sheetForm.sources} onChange={e => setSheetForm({ ...sheetForm, sources: e.target.value })} /></FormField></div><div className="md:col-span-2"><FormField label="Cómo se verifica la confiabilidad de las fuentes"><Textarea aria-label="Confiabilidad de fuentes" required value={sheetForm.sourceReliability} onChange={e => setSheetForm({ ...sheetForm, sourceReliability: e.target.value })} /></FormField></div><FormField label="Responsable de medición"><ReferenceInput field={{ key: "responsible", label: "Responsable de medición", section: "", required: true }} value={sheetForm.responsibleId} options={catalogs.people} onChange={v => setSheetForm({ ...sheetForm, responsibleId: text(v) })} /></FormField><div className="md:col-span-2"><FormField label="Actividades del plan de trabajo relacionadas"><ReferenceInput field={{ key: "workActivities", label: "Actividades del plan de trabajo", section: "", multiple: true, reference: "workActivities" }} value={sheetForm.workActivityIds} options={catalogs.workActivities.filter(o => o.year === year)} onChange={v => setSheetForm({ ...sheetForm, workActivityIds: ids(v) })} /></FormField></div></form> : sheetTarget && <div className="space-y-5"><p className="text-sm">{sheetTarget.description}</p><p className="rounded-md bg-blue-50 p-3 text-sm text-blue-900 dark:bg-blue-950 dark:text-blue-100">{formulaLabel(sheetTarget, state.rateConstant, state.costMethod)}</p><Link className="text-sm text-primary underline" href={sheetTarget.href}>Ver módulo de origen</Link><IndicatorHistory definition={sheetTarget} measurements={state.measurements.filter(m => m.indicatorId === sheetTarget.id && m.year === year)} onDetail={setDetailId} onRectify={m => openMeasurement(sheetTarget, m)} onUpload={m => openUpload({ scope: "measurement", id: m.id })} /></div>}
    </Modal>
    <Modal open={!!measurementTarget} onOpenChange={open => !open && setMeasurementTarget(null)} title={rectifying ? "Rectificar medición" : "Registrar medición"} footer={<><Button variant="outline" onClick={() => setMeasurementTarget(null)}>Cancelar</Button><Button type="submit" form="pesv-indicator-measurement">Guardar medición</Button></>}>
      {measurementTarget && <form id="pesv-indicator-measurement" onSubmit={saveMeasurement} className="space-y-5"><p className="text-sm font-medium">{sheetFor(measurementTarget, measurementForm.year).name}</p><p className="text-sm text-primary">{formulaLabel(measurementTarget, rectifying?.rateConstant ?? state.rateConstant, rectifying?.costMethod ?? state.costMethod)}</p><div className="grid gap-4 md:grid-cols-2"><FormField label="Período"><select aria-label="Período de medición" className={selectClass} disabled={!!rectifying} value={measurementForm.period} onChange={e => setMeasurementForm({ ...measurementForm, period: e.target.value, numerator: "", denominator: "", sourceDetails: "" })}>{Array.from({ length: measurementTarget.frequency === "Mensual" ? 12 : measurementTarget.frequency === "Trimestral" ? 4 : 1 }, (_, i) => String(i + 1)).map(p => <option value={p} key={p}>{periodLabel(measurementTarget, p)} · {periodRange(measurementForm.year, measurementTarget.frequency, p).end}</option>)}</select></FormField>{measurementTarget.loss && <FormField label="Nivel de pérdida"><select aria-label="Nivel de pérdida" className={selectClass} disabled={!!rectifying} value={measurementForm.loss} onChange={e => setMeasurementForm({ ...measurementForm, loss: e.target.value })}>{losses.map(l => <option key={l}>{l}</option>)}</select></FormField>}<FormField label={measurementTarget.numerator}><Input aria-label="Numerador" required type="number" min={0} step={measurementTarget.formula === "COST" ? "any" : 1} value={measurementForm.numerator} onChange={e => setMeasurementForm({ ...measurementForm, numerator: e.target.value })} /></FormField><FormField label={measurementTarget.denominator}><Input aria-label="Denominador" required type="number" min={0} step={measurementTarget.formula === "COST" || measurementTarget.formula === "RATE" ? "any" : 1} value={measurementForm.denominator} onChange={e => setMeasurementForm({ ...measurementForm, denominator: e.target.value })} /></FormField></div><div className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm">Resultado: <strong>{measurementForm.numerator === "" || measurementForm.denominator === "" ? "Pendiente de variables" : resultLabel(compute(measurementTarget, Number(measurementForm.numerator), Number(measurementForm.denominator), rectifying?.rateConstant ?? state.rateConstant, rectifying?.costMethod ?? state.costMethod), measurementTarget)}</strong></p>{["work", "maintenance", "training", "goals", "coverage", "inspections"].includes(measurementTarget.id) && <Button type="button" variant="outline" onClick={suggestMeasurement}><FileCheck2 className="mr-2 h-4 w-4" />Consultar módulos</Button>}</div>{measurementForm.sourceDetails && <p className="border-l-2 border-blue-300 pl-3 text-xs text-muted-foreground">{measurementForm.sourceDetails}</p>}<FormField label="Fuente utilizada en este corte"><Textarea aria-label="Fuente del corte" required value={measurementForm.source} onChange={e => setMeasurementForm({ ...measurementForm, source: e.target.value })} /></FormField><FormField label="Análisis del resultado y acciones"><Textarea aria-label="Análisis de medición" required value={measurementForm.analysis} onChange={e => setMeasurementForm({ ...measurementForm, analysis: e.target.value })} /></FormField>{rectifying && <FormField label="Motivo de rectificación"><Textarea aria-label="Motivo de rectificación" required value={measurementForm.correctionReason} onChange={e => setMeasurementForm({ ...measurementForm, correctionReason: e.target.value })} /></FormField>}</form>}
      {measurementTarget && ["tsv", "cost", "audit"].includes(measurementTarget.id) && <Button variant="outline" onClick={suggestMeasurement}><FileCheck2 className="mr-2 h-4 w-4" />Consultar registro PESV</Button>}
    </Modal>
    <Modal open={!!currentDetail} onOpenChange={open => !open && setDetailId(null)} title={currentDetail?.sheet.name ?? "Detalle de medición"}>
      {currentDetail && <div className="space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><Badge variant="outline">{periodLabel(currentDetail.definition, currentDetail.period)} · {currentDetail.year}</Badge><Button variant="outline" size="sm" onClick={() => downloadMeasurement(currentDetail)}><Download className="mr-2 h-4 w-4" />Descargar ficha</Button></div><p className="text-lg font-semibold">{resultLabel(currentDetail.result, currentDetail.definition)}</p><p className="text-sm">{formulaLabel(currentDetail.definition, currentDetail.rateConstant, currentDetail.costMethod)}</p><dl className="grid gap-4 md:grid-cols-2">{[[currentDetail.definition.numerator, String(currentDetail.numerator)], [currentDetail.definition.denominator, String(currentDetail.denominator)], ["Línea base / meta", `${currentDetail.sheet.baseline} / ${currentDetail.sheet.target}`], ["Nivel de pérdida", currentDetail.loss || "General"], ["Fuente", `${currentDetail.source}\n${currentDetail.sourceDetails}`], ["Análisis", currentDetail.analysis], ["Confiabilidad", currentDetail.sheet.sourceReliability], ["Actividades relacionadas", currentDetail.sheet.workActivityNames.join("; ") || "Sin relación específica"], ["Rectificación", currentDetail.correctionReason || "Medición original"]].map(([label, value]) => <div key={label}><dt className="text-xs text-muted-foreground">{label}</dt><dd className="mt-1 whitespace-pre-wrap break-words text-sm">{value}</dd></div>)}</dl><EvidenceList evidence={currentDetail.evidence} onPreview={setPreview} /></div>}
    </Modal>
    <Modal open={reviewOpen} onOpenChange={setReviewOpen} title="Nueva revisión del Comité de Seguridad Vial" footer={<><Button variant="outline" onClick={() => setReviewOpen(false)}>Cancelar</Button><Button form="pesv-csv-review" type="submit" disabled={!committeeMembers.length}>Guardar revisión</Button></>}><form id="pesv-csv-review" onSubmit={saveReview} className="space-y-4"><div className="grid gap-4 md:grid-cols-2"><FormField label="Trimestre"><select aria-label="Trimestre de revisión" className={selectClass} value={reviewForm.quarter} onChange={e => setReviewForm({ ...reviewForm, quarter: e.target.value })}>{["1", "2", "3", "4"].map(q => <option key={q} value={q}>Trimestre {q} · {quarterEnd(reviewForm.year, q)}</option>)}</select></FormField><FormField label="Fecha de revisión"><Input aria-label="Fecha de revisión CSV" type="date" required min={quarterEnd(reviewForm.year, reviewForm.quarter)} max={dateToday()} value={reviewForm.date} onChange={e => setReviewForm({ ...reviewForm, date: e.target.value })} /></FormField></div><FormField label="Miembros del CSV que revisan"><ReferenceInput field={{ key: "reviewers", label: "Miembros del CSV", section: "", multiple: true }} value={reviewForm.reviewers} options={committeeMembers} onChange={v => setReviewForm({ ...reviewForm, reviewers: ids(v) })} /></FormField>{!committeeMembers.length && <Link className="text-sm text-primary underline" href="/dashboard/pesv-committee">Comité de Seguridad Vial pendiente de conformación</Link>}<FormField label="Conclusiones del análisis"><Textarea aria-label="Conclusiones CSV" required value={reviewForm.conclusion} onChange={e => setReviewForm({ ...reviewForm, conclusion: e.target.value })} /></FormField><FormField label="Decisiones, acciones, responsables y plazos"><Textarea aria-label="Decisiones CSV" required value={reviewForm.decisions} onChange={e => setReviewForm({ ...reviewForm, decisions: e.target.value })} /></FormField></form></Modal>
    <Modal open={!!currentReview} onOpenChange={open => !open && setReviewDetail(null)} title="Revisión trimestral del CSV">{currentReview && <div className="space-y-4"><p className="text-sm">Corte {quarterEnd(currentReview.year, currentReview.quarter)} · Revisión {currentReview.date}</p><p className="text-sm">{currentReview.reviewerNames.join(" · ")}</p><h3 className="font-semibold">Conclusiones</h3><p className="whitespace-pre-wrap text-sm">{currentReview.conclusion}</p><h3 className="font-semibold">Decisiones y acciones</h3><p className="whitespace-pre-wrap text-sm">{currentReview.decisions}</p><MeasurementTable measurements={currentReview.measurements} /><EvidenceList evidence={currentReview.evidence} onPreview={setPreview} /></div>}</Modal>
    <Modal open={reportOpen} onOpenChange={setReportOpen} title="Generar reporte anual de autogestión" footer={<><Button variant="outline" onClick={() => setReportOpen(false)}>Cancelar</Button><Button form="pesv-autogestion" type="submit">Guardar versión del reporte</Button></>}><form id="pesv-autogestion" onSubmit={saveReport} className="space-y-6"><SchemaFields kind={annualReportKind} values={reportForm} catalogs={catalogs} onChange={(key, value) => setReportForm({ ...reportForm, [key]: value })} />{([ ["fleet", "Flota por tipo y vinculación"], ["actors", "Colaboradores por actor vial"], ["contractors", "Contratistas, subcontratistas y terceros"], ["fines", "Infracciones por tipo o código"] ] as const).map(([key, title]) => <ReportRowsEditor key={key} title={title} rows={reportRows[key]} onChange={rows => setReportRows({ ...reportRows, [key]: rows })} />)}<section className="space-y-4 border-t pt-5"><h3 className="font-semibold text-primary">Resumen de la última auditoría · 24 pasos</h3>{steps.map(step => <div className="grid min-w-0 gap-3 border-b pb-3 md:grid-cols-[minmax(0,1fr)_10rem]" key={step.step}><p className="text-sm font-medium">{step.step}. {stepNames[step.step - 1]}</p><select className={selectClass} aria-label={`Estado del paso ${step.step}`} value={step.status} onChange={e => setSteps(prev => prev.map(s => s.step === step.step ? { ...s, status: e.target.value as StepResult["status"] } : s))}>{["Sin evaluar", "Cumple", "No cumple", "No aplica"].map(s => <option key={s}>{s}</option>)}</select><div className="md:col-span-2"><Textarea aria-label={`Observaciones del paso ${step.step}`} placeholder={step.status === "No aplica" ? "Fundamento de no aplicabilidad" : "Resultado y soporte de auditoría"} value={step.observations} onChange={e => setSteps(prev => prev.map(s => s.step === step.step ? { ...s, observations: e.target.value } : s))} /></div></div>)}</section></form></Modal>
    <Modal open={!!currentReport} onOpenChange={open => !open && setReportDetail(null)} title="Reporte de autogestión y soportes">{currentReport && <div className="space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><p className="font-semibold">{text(currentReport.values.companyName)} · {text(currentReport.values.year)}</p><Button variant="outline" onClick={() => downloadAnnualReport(currentReport)}><Download className="mr-2 h-4 w-4" />Descargar PDF</Button></div><ReportPending report={currentReport} /><p className="text-sm whitespace-pre-wrap">{text(currentReport.values.analysis)}</p><MeasurementTable measurements={currentReport.measurements} /><h3 className="font-semibold">Informe de auditoría interna</h3><EvidenceList evidence={currentReport.evidence.filter(e => e.targetId === "AUDIT")} onPreview={setPreview} /><h3 className="font-semibold">Documento firmado</h3><EvidenceList evidence={currentReport.evidence.filter(e => e.targetId === "SIGNED")} onPreview={setPreview} /><h3 className="font-semibold">Radicación</h3><EvidenceList evidence={currentReport.evidence.filter(e => e.targetId === "RECEIPT")} onPreview={setPreview} />{currentReport.presentations.map(p => <p className="text-sm" key={p.at}>{p.date} · {p.authority} · Radicado {p.reference}</p>)}</div>}</Modal>
    <Modal open={protocolOpen} onOpenChange={setProtocolOpen} title="Protocolo y metodología de indicadores" footer={<><Button variant="outline" onClick={() => setProtocolOpen(false)}>Cancelar</Button><Button form="pesv-indicator-protocol" type="submit">Guardar protocolo</Button></>}><form id="pesv-indicator-protocol" onSubmit={saveProtocol} className="space-y-5"><SchemaFields kind={protocolKind} values={protocolForm} catalogs={catalogs} onChange={(key, value) => setProtocolForm({ ...protocolForm, [key]: value })} /><section className="space-y-4 border-t pt-5"><h3 className="font-semibold text-primary">Aplicabilidad y convenciones de cálculo</h3><FormField label="Nivel del PESV"><select aria-label="Nivel del PESV" className={selectClass} value={levelForm} onChange={e => setLevelForm(e.target.value as Level)}>{["Básico", "Estándar", "Avanzado"].map(l => <option key={l}>{l}</option>)}</select></FormField><FormField label="Constante K de kilómetros para la tasa de siniestros"><Input aria-label="Constante K" required type="number" min={1} step="any" value={constantForm} onChange={e => setConstantForm(e.target.value)} /></FormField><FormField label="Método de costos de siniestros"><select aria-label="Método de costos" className={selectClass} value={costMethodForm} onChange={e => setCostMethodForm(e.target.value as "SUM" | "PRODUCT")}><option value="SUM">Costo total: directos + indirectos</option><option value="PRODUCT">Transcripción literal: directos × indirectos (por validar)</option></select></FormField><p className="border-l-2 border-amber-400 pl-3 text-sm text-amber-800">La tabla de referencia presenta inconsistencias en símbolos y constantes. La organización debe validar la convención de cálculo antes de presentar el reporte.</p></section></form></Modal>
    <Modal open={!!uploadTarget} onOpenChange={open => !uploading && !open && setUploadTarget(null)} title="Cargar documento de soporte" footer={<><Button variant="outline" disabled={uploading} onClick={() => setUploadTarget(null)}>Cancelar</Button><Button form="pesv-indicator-upload" type="submit" disabled={!file || uploading}>{uploading ? "Cargando…" : "Cargar evidencia"}</Button></>}><form id="pesv-indicator-upload" onSubmit={upload}><FormField label="Seleccionar documento o imagen"><Input aria-label="Seleccionar evidencia" type="file" required accept={uploadTarget?.purpose === "AUDIT" ? "application/pdf" : "image/*,application/pdf"} onChange={e => setFile(e.target.files?.[0] ?? null)} /></FormField></form></Modal>
    <Modal open={!!preview} onOpenChange={open => !open && setPreview(null)} title={preview?.name || "Documento"} footer={preview && <Button asChild><a href={preview.url} download={preview.name}><Download className="mr-2 h-4 w-4" />Descargar</a></Button>}>{preview && <div className="h-[65dvh]">{preview.mime.startsWith("image/") ? <img className="h-full w-full object-contain" src={preview.url} alt={preview.name} /> : <iframe className="h-full w-full" src={preview.url} title={preview.name} />}</div>}</Modal>
    <Modal open={!!presentationTarget} onOpenChange={open => !open && setPresentationTarget(null)} title="Registrar presentación realizada" footer={<Button form="pesv-report-presentation" type="submit">Registrar presentación</Button>}><form id="pesv-report-presentation" onSubmit={savePresentation} className="space-y-4"><FormField label="Fecha de presentación"><Input aria-label="Fecha de presentación" type="date" required max={dateToday()} value={presentationForm.date} onChange={e => setPresentationForm({ ...presentationForm, date: e.target.value })} /></FormField><FormField label="Autoridad destinataria"><Input aria-label="Autoridad destinataria" required value={presentationForm.authority} onChange={e => setPresentationForm({ ...presentationForm, authority: e.target.value })} /></FormField><FormField label="Número de radicado / referencia"><Input aria-label="Número de radicado" required value={presentationForm.reference} onChange={e => setPresentationForm({ ...presentationForm, reference: e.target.value })} /></FormField></form></Modal>
  </div>
}

function Actions({ label, children }: { label: string; children: React.ReactNode }) { return <DropdownMenu><DropdownMenuTrigger asChild><Button size="icon" variant="ghost" aria-label={label}><MoreHorizontal className="h-4 w-4" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end">{children}</DropdownMenuContent></DropdownMenu> }
function Empty({ children }: { children: React.ReactNode }) { return <p className="p-7 text-center text-sm text-muted-foreground">{children}</p> }
function SchemaFields({ kind, values, catalogs, onChange }: { kind: typeof protocolKind; values: Values; catalogs: Catalogs; onChange: (key: string, value: string | string[]) => void }) { return <>{[...new Set(kind.fields.map(f => f.section))].map(section => <section className="space-y-4 border-b pb-5" key={section}><h3 className="font-semibold text-primary">{section}</h3><div className="grid gap-4 md:grid-cols-2">{kind.fields.filter(f => f.section === section).map(f => <div className={f.wide ? "min-w-0 md:col-span-2" : "min-w-0"} key={f.key}><FormField label={`${f.label} *`}><FieldInput field={f} value={values[f.key] || ""} catalogs={catalogs} onChange={v => onChange(f.key, v)} /></FormField></div>)}</div></section>)}</> }
function ReportRowsEditor({ title, rows, onChange }: { title: string; rows: ReportRow[]; onChange: (rows: ReportRow[]) => void }) { return <section className="space-y-3 border-t pt-5"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-semibold text-primary">{title}</h3><Button variant="outline" size="sm" type="button" onClick={() => onChange([...rows, { id: crypto.randomUUID(), label: "", category: "", count: 0 }])}><Plus className="mr-2 h-4 w-4" />Agregar fila</Button></div>{rows.map((row, i) => <div className="grid min-w-0 gap-3 border-b pb-3 md:grid-cols-[minmax(0,1fr)_minmax(0,1fr)_7rem_auto]" key={row.id}><Input required aria-label={`${title}: identificación ${i + 1}`} placeholder="Tipo / código / identificación" value={row.label} onChange={e => onChange(rows.map(r => r.id === row.id ? { ...r, label: e.target.value } : r))} /><Input aria-label={`${title}: categoría ${i + 1}`} placeholder="Categoría / vinculación" value={row.category} onChange={e => onChange(rows.map(r => r.id === row.id ? { ...r, category: e.target.value } : r))} /><Input required aria-label={`${title}: cantidad ${i + 1}`} type="number" min={0} step={1} value={row.count} onChange={e => onChange(rows.map(r => r.id === row.id ? { ...r, count: Number(e.target.value) } : r))} /><Button variant="ghost" size="sm" type="button" onClick={() => onChange(rows.filter(r => r.id !== row.id))}>Quitar</Button></div>)}</section> }
function MeasurementTable({ measurements }: { measurements: Measurement[] }) { return <div className="overflow-x-auto"><table className="w-full text-sm"><thead className={tableHead}><tr>{["Indicador / período", "Resultado", "Análisis"].map(l => <th className={cell} key={l}>{l}</th>)}</tr></thead><tbody>{measurements.map(m => <tr className="border-b" key={m.id}><td className={`${cell} min-w-48`}>{m.sheet.name}<p className="text-xs text-muted-foreground">{periodLabel(m.definition, m.period)} · {m.loss}</p></td><td className={cell}>{resultLabel(m.result, m.definition)}</td><td className={`${cell} min-w-48 whitespace-pre-wrap`}>{m.analysis}</td></tr>)}</tbody></table>{!measurements.length && <Empty>Sin mediciones incluidas.</Empty>}</div> }
function ReportPending({ report }: { report: AnnualReport }) { const warnings = reportWarnings(report, text(report.values.level) as Level); return warnings.length ? <section className="space-y-2 border-l-2 border-amber-400 pl-3"><h3 className="font-semibold text-amber-800">Pendientes del reporte</h3>{warnings.map(w => <p className="text-sm text-amber-800" key={w}>{w}</p>)}</section> : <Badge variant="outline" className="border-green-200 text-green-700">Información y soportes completos</Badge> }
function IndicatorHistory({ definition, measurements, onDetail, onRectify, onUpload }: { definition: IndicatorDefinition; measurements: Measurement[]; onDetail: (id: string) => void; onRectify: (m: Measurement) => void; onUpload: (m: Measurement) => void }) {
  const current = activeMeasurements(measurements)
  const [loss, setLoss] = useState(losses[0])
  const chart = current.filter(m => !definition.loss || m.loss === loss).sort((a, b) => Number(a.period) - Number(b.period)).map(m => ({ period: periodLabel(definition, m.period), value: m.result }))
  return <div className="space-y-4">{definition.loss && <select className={selectClass} aria-label="Nivel de pérdida de la gráfica" value={loss} onChange={e => setLoss(e.target.value)}>{losses.map(l => <option key={l}>{l}</option>)}</select>}{chart.some(p => p.value !== null) && <div className="h-48 w-full min-w-0"><ResponsiveContainer width="100%" height="100%"><LineChart data={chart} margin={{ top: 12, right: 12, bottom: 0, left: 0 }}><XAxis dataKey="period" tick={{ fontSize: 11 }} /><YAxis width={45} tick={{ fontSize: 11 }} /><ChartTooltip /><Line dataKey="value" name={definition.unit} type="monotone" stroke="#2563eb" strokeWidth={2} connectNulls={false} /></LineChart></ResponsiveContainer></div>}<div className="overflow-x-auto"><table className="w-full text-sm"><thead className={tableHead}><tr>{["Período", "Resultado", "Versión", "Soportes", ""].map((l, i) => <th className={cell} key={i}>{l}</th>)}</tr></thead><tbody>{measurements.slice().reverse().map(m => <tr key={m.id} className="border-b"><td className={`${cell} whitespace-nowrap`}>{periodLabel(m.definition, m.period)}<p className="text-xs text-muted-foreground">{m.loss}</p></td><td className={cell}>{resultLabel(m.result, m.definition)}</td><td className={cell}><Badge variant="outline">{current.some(c => c.id === m.id) ? "Vigente" : "Rectificada"}</Badge></td><td className={cell}>{m.evidence.length || "Pendiente"}</td><td className={cell}><Actions label={`Acciones de medición ${m.id}`}><DropdownMenuItem onSelect={() => onDetail(m.id)}><Eye className="mr-2 h-4 w-4" />Ver medición</DropdownMenuItem><DropdownMenuItem onSelect={() => onUpload(m)}><Upload className="mr-2 h-4 w-4" />Cargar evidencia</DropdownMenuItem><DropdownMenuItem disabled={!current.some(c => c.id === m.id)} onSelect={() => onRectify(m)}><History className="mr-2 h-4 w-4" />Rectificar medición</DropdownMenuItem><DropdownMenuItem onSelect={() => downloadMeasurement(m)}><Download className="mr-2 h-4 w-4" />Descargar ficha</DropdownMenuItem></Actions></td></tr>)}</tbody></table>{!measurements.length && <Empty>Sin mediciones para esta vigencia.</Empty>}</div></div>
}
